def cleanup(self):
    for fname in os.listdir(self.root):
        if not fname.endswith(".json"):
            continue
        p = os.path.join(self.root, fname)
        try:
            with open(p) as f:
                rec = json.load(f)
            if self._now() - rec["t"] > self.ttl:
                os.remove(p)
        except (OSError, json.JSONDecodeError):
            os.remove(p)
